SELECT count(DISTINCT nconst) AS people_director_and_actor
FROM people
WHERE 'director' = ANY(professions) AND 'actor' = ANY(professions);

SELECT count(DISTINCT c.tconst) AS movies
FROM credits c
WHERE c.nconst = 'nm0594503' AND c.category = 'director';

SELECT ROUND(AVG(r.avg_rating)::numeric, 2) AS avg_rating, COUNT(DISTINCT c.tconst) AS movies
FROM credits c JOIN ratings r ON r.tconst = c.tconst
WHERE c.nconst = 'nm0000399' AND c.category = 'director';

SELECT count(DISTINCT c.tconst) AS movies
FROM credits c
WHERE c.nconst = 'nm0000115' AND c.category IN ('actor','actress');

SELECT count(DISTINCT c.tconst) AS movies_directed
FROM credits c
WHERE c.nconst = 'nm0000142' AND c.category = 'director';
